def parse_all(items):
    """Parse every string to int. If any fail, raise ONE ExceptionGroup holding all the failures."""
    numbers, failures = [], []
    for item in items:
        try:
            numbers.append(int(item))
        except ValueError:
            failures.append(ValueError(f"bad item: {item!r}"))
    if failures:
        raise ExceptionGroup("bad items", failures)
    return numbers

try:
    parse_all(["4", "x", "9", "y"])
except ExceptionGroup as eg:
    print(len(eg.exceptions))
    print(*[str(e) for e in eg.exceptions], sep="\n")
